SELECT id, symbol, interval_code, candle_open_time, generated_at, created_at, decision, original_decision, total_score, confidence_score, final_entry_allowed, primary_blocking_stage, data_quality_valid, latest_price, stop_loss, take_profit, risk_reward_ratio, atr_entry_type, atr_recommended_position_percent, atr_overextended, LEFT(decision_path, 4000) AS decision_path FROM crypto_ai.trade_signal WHERE id IN (159285, 159407, 165415, 176529, 176655) ORDER BY id;